let email = '';
const body = $('Webhook POST').first().json.body;
if (body.branding && body.branding.ownerEmail) {
  email = body.branding.ownerEmail.trim();
}
if (!email && body.ownerEmail) {
  email = body.ownerEmail.trim();
}
if (!email || !email.includes('@')) {
  try {
    const res = await fetch('https://estetica.neco-dev.cloud/branding.json');
    if (res.ok) {
      const data = await res.json();
      if (data.ownerEmail) email = data.ownerEmail.trim();
    }
  } catch (err) {}
}

const staffMap = {
  'S01': 'Valeria Gomez',
  'S02': 'Marcos Silva',
  'S03': 'Candela Gomez'
};

let staffNombre = (body.staffNombre || '').trim();
const rawStaff = (body.idStaff || '').trim();

if (!staffNombre || staffMap[staffNombre.toUpperCase()]) {
  staffNombre = staffMap[rawStaff.toUpperCase()] || staffMap[staffNombre.toUpperCase()] || rawStaff || 'Profesional Asignado';
}

return [{
  json: {
    ownerEmail: email,
    hasOwnerEmail: email.includes('@'),
    staffNombre: staffNombre
  }
}];
